import { delegate } from 'kerfjs';
import type { SafeHtml } from 'kerfjs';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { ValueTable } from '@kerfjs/ui/value-table';
import { EmptyState } from '@kerfjs/ui/empty-state';
import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import '@kerfjs/ui/webawesome.css';
import '@awesome.me/webawesome/dist/components/dialog/dialog.js';
import '@awesome.me/webawesome/dist/components/button/button.js';
import './project-dialog.css';

export interface Project { id: string; name: string; owner: string; status: string; updated: string; summary: string }
interface DialogElement extends HTMLElement { open: boolean }
export function mountProjectDialog(root: HTMLElement, paint: (content: SafeHtml) => void, id: string, projects: Project[], openProject: (id: string) => void) {
  let selected = projects[0]?.id;
  let open = false;
  let invoking: HTMLElement | null = null;
  const titleId = id + '-title';
  const summaryId = id + '-summary';
  const dialog = () => root.querySelector<DialogElement>('wa-dialog')!;
  const render = () => {
    const project = projects.find(item => item.id === selected);
    paint(<div class="project-dialog-host kui-layout">
      <button class="project-dialog-trigger" type="button" data-action="projects-show">Compare projects</button>
      <wa-dialog id={id} class="project-dialog" without-header label="Project details" aria-labelledby={titleId} aria-describedby={summaryId} open={open}>
        <DialogHeader title="Project details" titleId={titleId} summary="Select a project to compare its delivery status." summaryId={summaryId} actions={<wa-button appearance="plain" data-action="projects-close">Close</wa-button>} />
        <div class="project-dialog__body kui-dialog-body">
          <nav class="project-dialog__master kui-sidebar" aria-label="Projects">
            <MenuHeader label="Projects" />
            {projects.map(item => <MenuItem action="projects-select" itemId={item.id} label={item.name} selected={item.id === selected} multiline />)}
          </nav>
          <section class="project-dialog__detail kui-section-stack" aria-live="polite" aria-atomic="true">
            {project ? <><h3>{project.name}</h3><p>{project.summary}</p>
              <ValueTable label="Project metadata"><div><dt>Owner</dt><dd>{project.owner}</dd></div><div><dt>Status</dt><dd>{project.status}</dd></div><div><dt>Updated</dt><dd>{project.updated}</dd></div></ValueTable>
            </> : <EmptyState title="No projects available" detail="Close this dialog and create a project to get started." />}
          </section>
        </div>
        <div slot="footer" class="kui-control-cluster"><wa-button appearance="outlined" data-action="projects-close">Cancel</wa-button><wa-button variant="brand" appearance="accent" data-action="projects-open" disabled={!project}>Open project</wa-button></div>
      </wa-dialog>
    </div>);
  };
  const off = delegate(root, 'click', '[data-action]', (_event, element) => {
    switch (element.dataset.action) {
      case 'projects-show': invoking = element; invoking.focus(); open = true; dialog().open = true; break;
      case 'projects-close': dialog().open = false; break;
      case 'projects-select':
        if (!projects.some(item => item.id === element.dataset.itemId)) return;
        selected = element.dataset.itemId; render(); break;
      case 'projects-open':
        if (selected) { dialog().open = false; openProject(selected); } break;
    }
  });
  const afterHide = (event: Event) => {
    if (event.target !== dialog()) return;
    open = false;
    if (invoking?.isConnected) invoking.focus();
  };
  root.addEventListener('wa-after-hide', afterHide);
  render();
  return () => { off(); root.removeEventListener('wa-after-hide', afterHide); };
}

