.project-dialog { --spacing: var(--kui-layout-dialog-inset); --width: min(62rem, calc(100vw - 2 * var(--kui-layout-dialog-inset))); }
/* The dialog's production body is the sole scroll container. Remove its
   inset through its public token; our one body inset follows DialogHeader. */
.project-dialog { --spacing: 0; }
.project-dialog__body { display: grid; grid-template-columns: minmax(12rem, .8fr) minmax(0, 1.4fr); gap: var(--kui-layout-section-gap); }
.project-dialog__master { min-width: 0; border-inline-end: 1px solid var(--kui-color-border); }
.project-dialog__detail { min-width: 0; overflow-wrap: anywhere; }
.project-dialog__detail h3, .project-dialog__detail p { margin: 0; }
.project-dialog [slot="footer"] { padding: var(--kui-layout-dialog-inset); justify-content: flex-end; }
.project-dialog-trigger { font: inherit; min-height: 2.5rem; padding: var(--kui-space-xs) var(--kui-space-s); border: 1px solid var(--kui-color-border); border-radius: var(--kui-radius-m); background: var(--kui-color-surface); color: var(--kui-color-text); }
.project-dialog-trigger:focus-visible { outline: var(--kui-focus-ring); outline-offset: 2px; }
@media (max-width: 44rem) { .project-dialog__body { grid-template-columns: minmax(0, 1fr); } .project-dialog__master { border-inline-end: 0; border-block-end: 1px solid var(--kui-color-border); } }
